import sqlite3,yaml,collections
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
st=yaml.safe_load(open('governance/stage-map.yaml'))['tables']
T=[r[0] for r in c.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%'")]
n={t:c.execute(f'select count(*) from "{t}"').fetchone()[0] for t in T}
empty={t for t in T if n[t]==0}
by=collections.defaultdict(list)
for t in T: by[st.get(t,'UNMAPPED')].append(t)
for s in ['base','research','evidence','judgment','synthesis','specification','render','infrastructure','UNMAPPED']:
    ts=by.get(s,[])
    if not ts: continue
    print(f"{s:14} tables={len(ts):2} empty={sorted(t for t in ts if t in empty)}")
print('--UNWRITABLE')
for t in T:
    dead={f[3] for f in c.execute(f'PRAGMA foreign_key_list("{t}")') if f[2] in empty}
    for col in c.execute(f'PRAGMA table_info("{t}")'):
        if col[1] in dead and col[3]: print(' ',st.get(t),t,col[1])
PY
